```javascript
import { Group, Mesh, CylinderGeometry, PlaneGeometry, PointLight, Vector3 } from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, length, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // Cleanup tracking
  const timelines = [];
  const materials = [];
  const geometries = [];
  let primitiveResults = [];

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    materials.forEach(mat => mat.dispose());
    geometries.forEach(geo => geo.dispose());
    primitiveResults.forEach(r => r?.cleanup?.());
  };

  // === BACKDROP PLANE WITH GRADIENT ===
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial({
    roughness: 1.0,
    metalness: 0,
    side: ctx.THREE.BackSide
  });

  // Gradient: top dark #0b0b10 to bottom light #16161d
  const c0b0b10 = vec3(11/255, 11/255, 16/255);
  const c16161d = vec3(22/255, 22/255, 29/255);
  backdropMat.colorNode = mix(c16161d, c0b0b10, uv().y);

  const backdropPlane = new Mesh(backdropGeo, backdropMat);
  backdropPlane.position.z = -2.5;
  group.add(backdropPlane);
  materials.push(backdropMat);
  geometries.push(backdropGeo);

  // === PLINTH (CYLINDRICAL BASE) ===
  const plinthGeo = new CylinderGeometry(1.4, 1.4, 0.25, 32);
  const plinthMat = new MeshStandardNodeMaterial({
    color: 0x14141a,
    roughness: 0.7,
    metalness: 0.3
  });
  const plinth = new Mesh(plinthGeo, plinthMat);
  plinth.position.y = -1.225; // Top face at y=-1.1
  group.add(plinth);
  materials.push(plinthMat);
  geometries.push(plinthGeo);

  // === CONTACT SHADOW ===
  const shadowGeo = new PlaneGeometry(3.2, 3.2);
  const shadowMat = new MeshStandardNodeMaterial({
    color: 0x000000,
    transparent: true,
    depthWrite: false
  });

  // Radial gradient shadow using TSL
  const shadowUV = uv().sub(0.5).mul(2.0);
  const shadowDist = length(shadowUV);
  const shadowAlpha = smoothstep(1.5, 0, shadowDist).mul(0.55);
  shadowMat.opacityNode = shadowAlpha;

  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.position.y = -1.225;
  shadowPlane.rotation.x = -Math.PI / 2;
  group.add(shadowPlane);
  materials.push(shadowMat);
  geometries.push(shadowGeo);

  // === LOAD WATCH MESH ===
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const scene = gltf.scene;

    // Scale to 2.2 units tall
    const bbox = new ctx.THREE.Box3().setFromObject(scene);
    const size = bbox.getSize(new Vector3());
    const scale = 2.2 / size.y;
    scene.scale.multiplyScalar(scale);

    // Center at origin
    const centerBbox = new ctx.THREE.Box3().setFromObject(scene);
    const center = centerBbox.getCenter(new Vector3());
    scene.position.sub(center);

    // Apply PBR material
    scene.traverse((node) => {
      if (node.isMesh) {
        const baseColor = node.material?.color?.getHex?.() || 0x999999;
        const watchMat = new MeshStandardNodeMaterial({
          color: baseColor,
          roughness: 0.52,
          metalness: 0.55,
          clearcoat: 0.2,
          clearcoatRoughness: 0.4
        });
        node.material = watchMat;
        materials.push(watchMat);
      }
    });

    group.add(scene);
  });

  // === TEXT ELEMENTS ===
  const headline = ctx.fontAtlas.createText('Calibre NA-01', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center'
  });
  headline.position.y = -1.5;
  group.add(headline);

  const bodyText = ctx.fontAtlas.createText('Machined in-house. 41 mm. Grade 5 titanium.', {
    fontSize: 26,
    color: '#e8ecf2',
    align: 'center'
  });
  bodyText.position.y = -2.0;
  group.add(bodyText);

  const caption = ctx.fontAtlas.createText('FROM 4200 USD / SHIPS IN 21 DAYS', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.44
  });
  caption.position.y = -2.5;
  group.add(caption);

  // === LIGHTING ===
  // Rim/accent light grazing left case flank
  const rimLight = new PointLight(0xff2a38, 0.9);
  rimLight.position.set(-3.0, 1.0, 2.0);
  group.add(rimLight);

  // === CINEMATIC PRIMITIVES ===
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      if (prim.trigger === 'load') {
        const result = ctx.primitives[prim.name](group, prim.params);
        if (result?.cleanup) {
          primitiveResults.push(result);
        }
      } else if (prim.trigger === 'hover') {
        group.userData.hoverPrim = prim;
      }
    });

    // Hover handler for depth-rotate
    if (group.userData.hoverPrim) {
      group.userData.handlers.onMouseEnter = () => {
        const { name, params } = group.userData.hoverPrim;
        const result = ctx.primitives[name](group, params);
        if (result?.cleanup) {
          primitiveResults.push(result);
        }
      };
    }
  }

  return group;
}
